sys_script_include.script:
var RewardUtils = Class.create();
RewardUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	getDepartment: function(){
		var empId = this.getParameter('sysparm_empid');

		var userGr = new GlideRecordSecure('sys_user');
		if(userGr.get(empId)){
			return userGr.getValue('department');
		}
		return '';
	},

	getRemainingBudget: function(){
		var dept = this.getParameter('sysparm_dept');
		var quarter = this.getParameter('sysparm_quarter');
		var year = this.getParameter('sysparm_year');
	},

    type: 'RewardUtils'
});
